        // Bind then immediately drop a listener to obtain a loopback port that refuses
        // connections — a deterministic "metadata document unreachable" target.
        let port = {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            listener.local_addr().unwrap().port()
        };
        let client_id = format!("http://127.0.0.1:{port}/oauth/client-metadata.json");

        let response = par_with_client_id(state, &client_id).await;

        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
        let json = error_json(response).await;
        assert_eq!(json["error"].as_str(), Some("invalid_client"));
        assert!(
            json["error_description"]
                .as_str()
                .unwrap()
                .contains("failed to fetch"),
            "unreachable metadata must be reported as a fetch failure, got: {}",
            json["error_description"]
        );
    }

    #[tokio::test]
    async fn post_par_rejects_http_url_client_id_for_non_loopback_host() {
        let state = test_state().await;

        let response =
            par_with_client_id(state, "http://app.example.com/client-metadata.json").await;

        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
        let json = error_json(response).await;
        assert_eq!(json["error"].as_str(), Some("invalid_client"));
        assert!(
            json["error_description"].as_str().unwrap().contains("https"),
            "plain-http client_id on a non-loopback host must be rejected before any fetch, got: {}",
            json["error_description"]
        );
    }

    // ── Reverse-FQDN rule for private-use-scheme redirect URIs ─────────────────

    #[test]
    fn private_use_redirect_scheme_must_reverse_client_id_host() {
        use super::validate_private_use_redirect;

        // Matching reverse-FQDN passes.
        assert!(validate_private_use_redirect(
            "https://identitywallet.obsign.org/oauth/client-metadata.json",
            "org.obsign.identitywallet:/oauth/callback",
        )
        .is_ok());

        // Mismatched scheme is rejected, naming the required scheme.
        let err = validate_private_use_redirect(
            "https://ezpds-staging.up.railway.app/oauth/client-metadata.json",
            "dev.malpercio.identitywallet:/oauth/callback",
        )
        .unwrap_err();
        assert!(
            err.contains("app.railway.up.ezpds-staging:"),
            "the error must name the required reverse-FQDN scheme, got: {err}"
        );

        // Scheme comparison is case-insensitive.
        assert!(validate_private_use_redirect(
            "https://IdentityWallet.Obsign.Org/oauth/client-metadata.json",
            "org.obsign.identitywallet:/oauth/callback",
        )
        .is_ok());
    }

    #[test]
    fn private_use_redirect_rule_exemptions() {
        use super::validate_private_use_redirect;

        // https redirect URIs are not private-use schemes.
        assert!(validate_private_use_redirect(
            "https://app.example.com/client-metadata.json",
            "https://app.example.com/callback",
        )
        .is_ok());

        // Loopback-http client_ids (local development) are exempt.
        assert!(validate_private_use_redirect(
            "http://localhost:8080/oauth/client-metadata.json",
            "org.obsign.identitywallet:/oauth/callback",
        )
        .is_ok());

        // Non-URL client_ids (operator-registered rows) are exempt.
        assert!(validate_private_use_redirect(
            "dev.malpercio.identitywallet",
            "dev.malpercio.identitywallet:/oauth/callback",
        )
        .is_ok());
    }

    #[tokio::test]
    async fn post_par_rejects_private_use_redirect_not_matching_reverse_fqdn() {
        let state = test_state().await;
        // A registered discoverable client whose metadata lists a custom-scheme
        // redirect that does NOT reverse the client_id host.
        register_oauth_client(
            &state.db,
            CLIENT_ID,
            r#"{"redirect_uris":["dev.other.app:/oauth/callback"],"client_name":"Test App"}"#,
        )
        .await
        .unwrap();

        let response = app(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/oauth/par")
                    .header("content-type", "application/x-www-form-urlencoded")
                    .body(Body::from(par_body(&[(
                        "redirect_uri",
                        "dev.other.app:/oauth/callback",
                    )])))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
        let json = error_json(response).await;
        assert_eq!(json["error"].as_str(), Some("invalid_redirect_uri"));
        assert!(
            json["error_description"]
                .as_str()
                .unwrap()
                .contains("com.example.app:"),
            "the rejection must name the required reverse-FQDN scheme, got: {}",
            json["error_description"]
        );
    }

    #[tokio::test]
    async fn post_par_accepts_private_use_redirect_matching_reverse_fqdn() {
        let state = test_state().await;
        register_oauth_client(
            &state.db,
            CLIENT_ID,
            r#"{"redirect_uris":["com.example.app:/oauth/callback"],"client_name":"Test App"}"#,
        )
        .await
        .unwrap();

        let response = app(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/oauth/par")
                    .header("content-type", "application/x-www-form-urlencoded")
                    .body(Body::from(par_body(&[(
                        "redirect_uri",
                        "com.example.app:/oauth/callback",
                    )])))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(
            response.status(),
            StatusCode::CREATED,
            "a reverse-FQDN-matching private-use redirect must be accepted"
        );
    }

    #[tokio::test]
    async fn post_par_freshly_fetched_loopback_client_is_exempt_from_reverse_fqdn() {
        // The freshly-fetched (unregistered URL client_id) branch resolves metadata live via
        // resolve_client_metadata. The harness serves it over loopback http, which is the spec's
        // local-development exception, so its private-use redirect is NOT held to the reverse-FQDN
        // rule even though the scheme doesn't reverse the (loopback) host. This exercises the new
        // check on the fetch branch and pins that exemption. The rule itself — for https URL
        // client_ids — is covered by the registered-client tests above, since redirect validation
        // runs after and independent of the registered-vs-fetched branch.
        let state = test_state().await;
        let client_id = serve_client_metadata(|url| {
            serde_json::json!({
                "client_id": url,
                "redirect_uris": ["dev.anything.at.all:/oauth/callback"],
            })
            .to_string()
        })
        .await;

        let response = app(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/oauth/par")
                    .header("content-type", "application/x-www-form-urlencoded")
                    .body(Body::from(par_body(&[
                        ("client_id", client_id.as_str()),
                        ("redirect_uri", "dev.anything.at.all:/oauth/callback"),
                    ])))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(
            response.status(),
            StatusCode::CREATED,
            "a loopback-http fetched client is exempt from the reverse-FQDN rule (local-dev exception)"
        );
    }

    #[tokio::test]
    async fn post_par_accepts_optional_login_hint() {
        let state = test_state().await;
        register_client(&state).await;

        let response = app(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/oauth/par")
                    .header("content-type", "application/x-www-form-urlencoded")
                    .body(Body::from(par_body(&[("login_hint", "alice.example.com")])))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(
            response.status(),
            StatusCode::CREATED,
            "PAR with login_hint must succeed"
        );
    }
}

// pattern: Imperative Shell
//
// Gathers: public URL from config
// Processes: none (response shape is fixed by RFC 8414 and AT Protocol OAuth spec)
// Returns: JSON matching the OAuth 2.0 Authorization Server Metadata format (RFC 8414)

use axum::{
    extract::State,
    response::{IntoResponse, Json},
};
use serde::Serialize;

use crate::app::AppState;

/// RFC 8414 OAuth 2.0 Authorization Server Metadata response.
///
/// Field names are snake_case per the OAuth spec — intentionally different from the
/// camelCase used by XRPC/AT Protocol Lexicon endpoints in this codebase.
///
/// AT Protocol OAuth extensions:
/// - `scopes_supported`: the AT Protocol scopes this server recognises.
/// - `dpop_signing_alg_values_supported`: signals that DPoP (RFC 9449) is required.
/// - `token_endpoint_auth_methods_supported`: public clients + private_key_jwt per spec §1.2.
/// - `token_endpoint_auth_signing_alg_values_supported`: the JWS algs accepted for a
///   `private_key_jwt` client-assertion. AT Protocol clients sign these with ES256, and the
///   atproto OAuth metadata validator rejects a server that advertises `private_key_jwt`
///   without this field including `ES256` — omitting it breaks discovery for every client.
/// - `require_pushed_authorization_requests`: PAR is mandatory per AT Protocol OAuth spec.
/// - `authorization_response_iss_parameter_supported`: the AT Protocol OAuth metadata
///   validator requires this to be `true` (the authorization endpoint returns the RFC 9207
///   `iss` parameter in its responses, which `oauth_authorize.rs` emits).
/// - `client_id_metadata_document_supported`: the AT Protocol OAuth metadata validator
///   requires this to be `true` — clients are identified by a client-metadata-document URL
///   rather than pre-registration (resolved in `auth::oauth_client_resolution`).
/// - `agent_auth`: advertises the auth.md agent-registration discovery surface.
#[derive(Serialize)]
struct OAuthServerMetadata {
    issuer: String,
    authorization_endpoint: String,
    token_endpoint: String,
    revocation_endpoint: String,
    pushed_authorization_request_endpoint: String,
    jwks_uri: String,
    scopes_supported: Vec<String>,
    response_types_supported: Vec<String>,
    grant_types_supported: Vec<String>,
    token_endpoint_auth_methods_supported: Vec<String>,
    token_endpoint_auth_signing_alg_values_supported: Vec<String>,
    revocation_endpoint_auth_methods_supported: Vec<String>,
    code_challenge_methods_supported: Vec<String>,
    dpop_signing_alg_values_supported: Vec<String>,
    require_pushed_authorization_requests: bool,
    authorization_response_iss_parameter_supported: bool,
    client_id_metadata_document_supported: bool,
    agent_auth: AgentAuthMetadata,
}

#[derive(Serialize)]
struct AgentAuthMetadata {
    skill: String,
    identity_endpoint: String,
    claim_endpoint: String,
    events_endpoint: String,
    identity_types_supported: Vec<String>,
    identity_assertion: IdentityAssertionMetadata,
    events_supported: Vec<String>,
}

#[derive(Serialize)]
struct IdentityAssertionMetadata {
    assertion_types_supported: Vec<String>,
}

pub async fn oauth_server_metadata(State(state): State<AppState>) -> impl IntoResponse {
    let base = state.config.public_url.trim_end_matches('/');
    Json(OAuthServerMetadata {
        issuer: base.to_string(),
        authorization_endpoint: format!("{base}/oauth/authorize"),
        token_endpoint: format!("{base}/oauth/token"),
        revocation_endpoint: format!("{base}/oauth/revoke"),
        pushed_authorization_request_endpoint: format!("{base}/oauth/par"),
        jwks_uri: format!("{base}/oauth/jwks"),
        scopes_supported: crate::auth::oauth_scopes::supported_scopes()
            .into_iter()
            .map(String::from)
            .collect(),
        response_types_supported: vec!["code".to_string()],
        grant_types_supported: vec![
            "authorization_code".to_string(),
            "refresh_token".to_string(),
            "urn:ietf:params:oauth:grant-type:jwt-bearer".to_string(),
            "urn:workos:agent-auth:grant-type:claim".to_string(),
        ],
        token_endpoint_auth_methods_supported: vec![
            "none".to_string(),
            "private_key_jwt".to_string(),
        ],
        token_endpoint_auth_signing_alg_values_supported: vec!["ES256".to_string()],
        revocation_endpoint_auth_methods_supported: vec![
            "none".to_string(),
            "private_key_jwt".to_string(),
        ],
        code_challenge_methods_supported: vec!["S256".to_string()],
        dpop_signing_alg_values_supported: vec!["ES256".to_string()],
        require_pushed_authorization_requests: true,
        authorization_response_iss_parameter_supported: true,
        client_id_metadata_document_supported: true,
        agent_auth: AgentAuthMetadata {
            skill: format!("{base}/auth.md"),
            identity_endpoint: format!("{base}/agent/identity"),
            claim_endpoint: format!("{base}/agent/identity/claim"),
            events_endpoint: format!("{base}/agent/event/notify"),
            identity_types_supported: vec![
                "anonymous".to_string(),
                "identity_assertion".to_string(),
                "service_auth".to_string(),
            ],
            identity_assertion: IdentityAssertionMetadata {
                assertion_types_supported: vec![
                    "urn:ietf:params:oauth:token-type:id-jag".to_string()
                ],
            },
            events_supported: vec![crate::auth::issuer_trust::REVOKED_EVENT_TYPE.to_string()],
        },
    })
}

#[cfg(test)]
mod tests {
