"// OAuth callback handler
(async function() {
    if (!window.oauthManager) {
        document.getElementById('error-message').textContent = 'OAuth manager failed to load. Please try again.';
        document.getElementById('error-message').style.display = 'block';
        document.querySelector('.callback-spinner').style.display = 'none';
        document.querySelector('.callback-message').textContent = 'Error';
        return;
    }

    const oauthManager = window.oauthManager;

    window.addEventListener('oauth:login', async (e) => {
        const handle = e.detail?.handle || e.detail?.session?.handle || oauthManager.currentSession?.handle;
        const did = e.detail?.session?.did || oauthManager.currentSession?.did;
        const state = e.detail?.state;

        // New users (no sprite yet) go to the intro page to learn about rpg.actor
        if (oauthManager.isNewUser) {
            window.location.href = '/intro';
            return;
        }

        // Determine the true destination for this user after migration
        let destination = null;
        if (state && typeof state === 'string' && state.startsWith('/') && !state.startsWith('/oauth')) {
            destination = state;
        } else if (did) {
            try {
                const res = await fetch('/api/creator/check?did=' + encodeURIComponent(did));
                if (res.ok) {
                    const data = await res.json();
                    if (data && data.isCreator) {
                        localStorage.setItem('rpg_actor_is_creator', 'true');
                        localStorage.setItem('rpg_actor_is_creator_did', did);
                        destination = '/creator';
                    }
                }
            } catch { /* fall through */ }
        }
        if (!destination) destination = handle ? '/' + handle : '/';

        // Check if this user needs spinealign. If so, route through /generator
        // which has the full compositing pipeline. It will redirect to `destination`
        // once migration completes (or skip immediately if already done).
        if (did) {
            try {
                const saRes = await fetch('/api/spinealign/status?did=' + encodeURIComponent(did));
                if (saRes.ok) {
                    const { done } = await saRes.json();
                    if (!done) {
                        window.location.href = '/generator?spinealign=1&next=' + encodeURIComponent(destination);
                        return;
                    }
                }
            } catch { /* if status check fails, proceed normally */ }
        }

        window.location.href = destination;
    });

    try {
        await oauthManager.init();
        if (!oauthManager.currentSession) {
            window.location.href = '/login';
        }
    } catch (err) {
        document.getElementById('error-message').textContent = 'Login failed: ' + (err.message || 'Unknown error');
        document.getElementById('error-message').style.display = 'block';
        document.querySelector('.callback-spinner').style.display = 'none';
        document.querySelector('.callback-message').textContent = 'Login failed';
        setTimeout(function() { window.location.href = '/login'; }, 3000);
    }
})();
"

