1	// pattern: Functional Core
2	//
3	// Pure rendering functions for the OAuth consent UI. All inputs are plain data; all
4	// outputs are plain strings or Axum response types that carry no side effects.
5	// No I/O, no database, no AppState.
6	//
7	// Visual system: "The Sealed Credential" (see DESIGN.md). Brand fonts are served by the
8	// the PDS's own /static/fonts route (no third-party CDN — an auth page must not leak logins).
9	
10	use axum::http::StatusCode;
11	use axum::response::{Html, Redirect};
12	
13	// ── Public rendering functions ────────────────────────────────────────────────
14	
15	/// Build an OAuth error redirect (303) to `redirect_uri` with error parameters.
16	///
17	/// `issuer` is emitted as the RFC 9207 `iss` parameter. The AT Protocol OAuth metadata
18	/// advertises `authorization_response_iss_parameter_supported: true`, so a conformant
19	/// client validates `iss` on every authorization response — including error responses
20	/// (e.g. the user denying) — and rejects one that omits it.
21	pub(super) fn error_redirect(
22	    redirect_uri: &str,
23	    error: &str,
24	    description: &str,
25	    state: &str,
26	    issuer: &str,
27	) -> Redirect {
28	    let sep = if redirect_uri.contains('?') { '&' } else { '?' };
29	    let url = format!(
30	        "{}{}error={}&error_description={}&state={}&iss={}",
31	        redirect_uri,
32	        sep,
33	        encode_param(error),
34	        encode_param(description),
35	        encode_param(state),
36	        encode_param(issuer),
37	    );
38	    Redirect::to(&url)
39	}
40	
41	/// Render a standalone HTML error page for cases where redirecting is unsafe
42	/// (unknown `client_id`, mismatched `redirect_uri`).
43	pub(super) fn error_page(title: &str, message: &str) -> (StatusCode, Html<String>) {
44	    let mut html = String::with_capacity(2048);
45	    html.push_str(ERROR_PAGE_HEADER);
46	    html.push_str(&html_escape(title));
47	    html.push_str("</title>\n  <style>");
48	    html.push_str(FONT_FACES);
49	    html.push_str(ERROR_CSS);
50	    html.push_str("  </style>\n</head>\n<body>\n");
51	    html.push_str(
52	        "  <div class=\"card\">\n    <div class=\"top\">\n      <span class=\"seal alarm\">",
53	    );
54	    html.push_str(ICON_ALARM);
55	    html.push_str("</span>\n      <h1>");
56	    html.push_str(&html_escape(title));
57	    html.push_str("</h1>\n      <p class=\"err-msg\">");
58	    html.push_str(&html_escape(message));
59	    html.push_str("</p>\n    </div>\n  </div>\n</body>\n</html>");
60	    (StatusCode::BAD_REQUEST, Html(html))
61	}
62	
63	/// Build an authorization-code success redirect (303) back to the client, carrying the plaintext
64	/// `code`, the round-tripped `state`, and the RFC 9207 `iss` parameter. Shared by the password
65	/// consent path and the wallet-completion path so both emit byte-identical responses.
66	pub(super) fn build_code_redirect(
67	    redirect_uri: &str,
68	    code: &str,
69	    state: &str,
70	    issuer: &str,
71	) -> Redirect {
72	    let sep = if redirect_uri.contains('?') { '&' } else { '?' };
73	    let url = format!(
74	        "{}{}code={}&state={}&iss={}",
75	        redirect_uri,
76	        sep,
77	        encode_param(code),
78	        encode_param(state),
79	        encode_param(issuer),
80	    );
81	    Redirect::to(&url)
82	}
83	
84	/// The wallet-path data the consent page renders alongside the password form: the pending
85	/// request's high-entropy `request_id` (poll key + handoff/complete linkage), its human-typeable
86	/// `user_code`, and the requesting `origin` (snapshotted on creation, encoded into the scan QR
87	/// alongside the `request_id`). Present only when the GET handler created a pending request.
88	pub(super) struct WalletConsentPath<'a> {
89	    pub user_code: &'a str,
90	    pub request_id: &'a str,
91	    pub origin: Option<&'a str>,
92	}
93	
94	/// Custom URL scheme the identity wallet registers; the "Open in Obsign" handoff link targets it.
95	/// The wallet has no deep-link handler yet (ADR-0006 removed server-initiated redirects), so this
96	/// link may degrade to "copy the code" — the typed `user_code` is the guaranteed path.
97	const WALLET_HANDOFF_SCHEME: &str = "org.obsign.identitywallet";
98	
99	/// Render the OAuth consent + sign-in page.
100	///
101	/// All user-controlled values are HTML-escaped before insertion.
102	/// `login_hint` pre-populates the identifier field (from the ATProto `login_hint` param
103	/// or from a previous failed submission so the user can correct their handle).
104	/// `error` renders an error banner above the form when credential validation fails.
105	/// `wallet` renders the wallet-approval path (typed code + handoff link + status polling) above
106	/// the password form; `None` on a password-error re-render, where no pending request exists.
107	#[allow(clippy::too_many_arguments)]
108	pub(super) fn render_consent_page(
109	    client_name: &str,
110	    client_id: &str,
111	    redirect_uri: &str,
112	    code_challenge: &str,
113	    code_challenge_method: &str,
114	    state: &str,
115	    scope: &str,
116	    response_type: &str,
117	    public_url: &str,
118	    login_hint: Option<&str>,
119	    error: Option<&str>,
120	    wallet: Option<&WalletConsentPath>,
121	) -> String {
122	    // Monogram for the application mark — the first character of the client name.
123	    let app_initial = client_name
124	        .chars()
125	        .next()
126	        .map(|c| c.to_uppercase().to_string())
127	        .unwrap_or_else(|| "·".to_string());
128	
129	    // Build HTML by concatenation — avoids doubling all CSS braces for format!.
130	    let mut html = String::with_capacity(6144);
131	    html.push_str(CONSENT_PAGE_HEADER);
132	    html.push_str(FONT_FACES);
133	    html.push_str(CONSENT_CSS);
134	    html.push_str("  </style>\n</head>\n<body>\n");
135	    html.push_str("  <div class=\"card\">\n");
136	
137	    // Header: seal, title, subtitle.
138	    html.push_str("    <div class=\"top\">\n      <span class=\"seal\">");
139	    html.push_str(ICON_SEAL_LG);
140	    html.push_str("</span>\n      <h1>Authorize access</h1>\n");
141	    html.push_str("      <p class=\"sub\">An app wants to sign in as your identity. Review the request, then approve to continue.</p>\n    </div>\n");
142	    html.push_str("    <div class=\"rule\"></div>\n");
143	
144	    // Application.
145	    html.push_str("    <div class=\"section-label\">Application</div>\n");
146	    html.push_str("    <div class=\"app\">\n      <span class=\"app-mark\">");
147	    html.push_str(&html_escape(&app_initial));
148	    html.push_str("</span>\n      <span>\n        <div class=\"client-name\">");
149	    html.push_str(&html_escape(client_name));
150	    html.push_str("</div>\n        <div class=\"client-id\">");
151	    html.push_str(&html_escape(client_id));
152	    html.push_str("</div>\n      </span>\n    </div>\n");
153	
154	    // Wallet path: shown first because it is the primary path for sovereign / passwordless
155	    // accounts (which cannot use the password form at all). Scope reduction moves into the wallet
156	    // for this path — the granted set is chosen there, not with the checkboxes below.
157	    if let Some(w) = wallet {
158	        html.push_str(&render_wallet_path(w));
159	        html.push_str("    <div class=\"divider\"><span>or sign in with a password</span></div>\n");
160	    }
161	
162	    // The <form> opens BEFORE the permissions section: the `granted_scope` checkboxes
163	    // must be form members or the browser silently omits them from the POST, and the
164	    // consent reduction filter would strip every non-`atproto` grant the user approved.
165	    html.push_str("    <form method=\"POST\" action=\"/oauth/authorize\">\n");
166	
167	    // Permissions: `atproto` is the mandatory base — always granted, never a checkbox.
168	    // Everything else is grouped by resource type with a checked-by-default checkbox, so the
169	    // user can deny individual permissions before approving.
170	    html.push_str("    <div class=\"section-label\">Base access</div>\n");
171	    html.push_str(
172	        "    <div class=\"scopes\">\n        <span class=\"scope-tag\">atproto</span>\n    </div>\n",
173	    );
174	    html.push_str(&render_permission_groups(scope));
175	    html.push_str("    <p class=\"scope-note\">Uncheck anything you don't want to grant — the app will only be able to do what's left checked.</p>\n");
176	
177	    // Sign in.
178	    html.push_str("    <div class=\"section-label\">Sign in to approve</div>\n");
179	    if let Some(msg) = error {
180	        html.push_str("    <div class=\"error-banner\">");
181	        html.push_str(ICON_ALERT);
182	        html.push_str("<span>");
183	        html.push_str(&html_escape(msg));
184	        html.push_str("</span></div>\n");
185	    }
186	    for (name, value) in [
187	        ("client_id", client_id),
188	        ("redirect_uri", redirect_uri),
189	        ("code_challenge", code_challenge),
190	        ("code_challenge_method", code_challenge_method),
191	        ("state", state),
192	        ("scope", scope),
193	        ("response_type", response_type),
194	    ] {
195	        html.push_str(&format!(
196	            "      <input type=\"hidden\" name=\"{}\" value=\"{}\" />\n",
197	            name,
198	            html_escape(value)
199	        ));
200	    }
201	    // autocapitalize/autocorrect/spellcheck are all disabled: handles and DIDs are
202	    // case-sensitive, lowercase identifiers, so iOS's default first-letter capitalization
203	    // (and autocorrect) would silently mangle a typed identifier and break sign-in.
204	    html.push_str(&format!(
205	        "      <input type=\"text\" name=\"identifier\" placeholder=\"alice.bsky.social or did:plc:…\" \
206	         autocomplete=\"username\" autocapitalize=\"none\" autocorrect=\"off\" spellcheck=\"false\" \
207	         value=\"{}\" class=\"field mono\" />\n",
208	        html_escape(login_hint.unwrap_or(""))
209	    ));
210	    html.push_str(
211	        "      <input type=\"password\" name=\"password\" placeholder=\"Password\" \
212	         autocomplete=\"current-password\" class=\"field\" />\n",
213	    );
214	    html.push_str("      <div class=\"actions\">\n");
215	    html.push_str("        <button type=\"submit\" name=\"action\" value=\"deny\" class=\"btn btn-deny\">Deny</button>\n");
216	    html.push_str("        <button type=\"submit\" name=\"action\" value=\"approve\" class=\"btn btn-approve\">");
217	    html.push_str(ICON_SEAL_SM);
218	    html.push_str("Approve</button>\n");
219	    html.push_str("      </div>\n    </form>\n");
220	
221	    // Footer: which PDS is serving this page.
222	    html.push_str("    <div class=\"server-info\">");
223	    html.push_str(ICON_LOCK);
224	    html.push_str("<span>");
225	    html.push_str(&html_escape(public_url));
226	    html.push_str("</span></div>\n  </div>\n</body>\n</html>");
227	    html
228	}
229	
230	// ── Permission grouping ─────────────────────────────────────────────────────────
231	
232	/// Render every non-`atproto` scope token as a checked-by-default checkbox, grouped under a
233	/// resource-type heading. `atproto` is rendered separately by the caller — it's mandatory and
234	/// never a checkbox.
235	fn render_permission_groups(scope: &str) -> String {
236	    let mut groups: Vec<(&'static str, Vec<&str>)> = Vec::new();
237	    for token in scope.split_whitespace() {
238	        if token == "atproto" {
239	            continue;
240	        }
241	        let label = crate::auth::oauth_scopes::resource_group_label(token);
242	        match groups.iter_mut().find(|(l, _)| *l == label) {
243	            Some((_, tokens)) => tokens.push(token),
244	            None => groups.push((label, vec![token])),
245	        }
246	    }
247	
248	    let mut html = String::new();
249	    for (label, tokens) in groups {
250	        html.push_str("    <div class=\"section-label\">");
251	        html.push_str(&html_escape(label));
252	        html.push_str("</div>\n    <div class=\"permission-group\">\n");
253	        for token in tokens {
254	            let escaped = html_escape(token);
255	            html.push_str(&format!(
256	                "      <label class=\"permission-row\"><input type=\"checkbox\" name=\"granted_scope\" value=\"{escaped}\" checked /> <span class=\"mono\">{escaped}</span></label>\n"
257	            ));
258	        }
259	        html.push_str("    </div>\n");
260	    }
261	    html
262	}
263	
264	// ── Wallet approval path ────────────────────────────────────────────────────────
265	
266	/// The scan-QR / handoff payload: the wallet's private-use scheme carrying the pending request's
267	/// `request_id` and (informationally) the requesting `origin`. The wallet resolves and displays the
268	/// request **server-side by `request_id`** (it never trusts the QR contents for what it shows), so
269	/// the origin here is a snapshot for context/debugging only. The same string backs both the QR the
270	/// phone scans and the same-device "Open in Obsign" link.
271	fn wallet_handoff_uri(request_id: &str, origin: Option<&str>) -> String {
272	    let mut uri = format!(
273	        "{WALLET_HANDOFF_SCHEME}:/consent?request_id={}",
274	        encode_param(request_id)
275	    );
276	    if let Some(origin) = origin {
277	        uri.push_str("&origin=");
278	        uri.push_str(&encode_param(origin));
279	    }
280	    uri
281	}
282	
283	/// Render the wallet-approval block: a scan QR encoding the `request_id` (+ origin) for the
284	/// cross-device phone-scan path, the human-typeable `user_code` fallback (no camera / accessibility),
285	/// an "Open in Obsign" handoff link carrying the same payload for the same-device path, a live status
286	/// region, and a no-JS "I've approved — continue" form that POSTs to `/oauth/authorize/complete`. An
287	/// inline script polls `GET /oauth/authorize/status` (backing off on the `slow_down` 429) and, on
288	/// approval, submits the same completion form — so JS and no-JS reach the identical completion path.
289	fn render_wallet_path(w: &WalletConsentPath) -> String {
290	    let request_id = html_escape(w.request_id);
291	    let user_code = html_escape(w.user_code);
292	    let handoff = wallet_handoff_uri(w.request_id, w.origin);
293	    let mut html = String::with_capacity(2048);
294	    html.push_str("    <div class=\"section-label\">Approve in your wallet</div>\n");
295	    html.push_str("    <div class=\"wallet\" id=\"wallet-path\" data-request-id=\"");
296	    html.push_str(&request_id);
297	    html.push_str("\">\n");
298	    // Scan path first: the strongest cross-device channel (start from the page, no transcription).
299	    // Rendered only when the payload actually fits in a QR — otherwise the typed code below stands
300	    // in, and nothing about the fallback changes.
301	    if let Some(qr) = render_qr_svg(&handoff) {
302	        html.push_str(
303	            "      <p class=\"wallet-lead\">Scan this with Obsign on your phone to sign in with your device key:</p>\n",
304	        );
305	        html.push_str("      <div class=\"qr\">");
306	        html.push_str(&qr);
307	        html.push_str("</div>\n");
308	        html.push_str(
309	            "      <p class=\"wallet-lead wallet-or\">No camera? Open Obsign and enter this code:</p>\n",
310	        );
311	    } else {
312	        html.push_str(
313	            "      <p class=\"wallet-lead\">Open Obsign and enter this code to sign in with your device key:</p>\n",
314	        );
315	    }
316	    html.push_str("      <div class=\"user-code mono\">");
317	    html.push_str(&user_code);
318	    html.push_str("</div>\n");
319	    html.push_str("      <a class=\"btn btn-approve wallet-open\" href=\"");
320	    html.push_str(&html_escape(&handoff));
321	    html.push_str("\">");
322	    html.push_str(ICON_SEAL_SM);
323	    html.push_str("Open in Obsign</a>\n");
324	    html.push_str(
325	        "      <p class=\"wallet-status\" id=\"wallet-status\" role=\"status\" aria-live=\"polite\">Waiting for approval in your wallet…</p>\n",
326	    );
327	    html.push_str(
328	        "      <form method=\"POST\" action=\"/oauth/authorize/complete\" id=\"complete-form\">\n",
329	    );
330	    html.push_str("        <input type=\"hidden\" name=\"request_id\" value=\"");
331	    html.push_str(&request_id);
332	    html.push_str("\" />\n");
333	    html.push_str(
334	        "        <button type=\"submit\" class=\"btn btn-deny wallet-continue\">I've approved — continue</button>\n",
335	    );
336	    html.push_str("      </form>\n");
337	    html.push_str("    </div>\n");
338	    html.push_str(WALLET_POLL_SCRIPT);
339	    html
340	}
341	
342	/// Inline poller for the wallet path. Reads the `request_id` from the block's data attribute, polls
343	/// the status endpoint on a backoff that widens when it sees the `slow_down` 429, and submits the
344	/// completion form on approval. If CSP or a JS-off client blocks it, the no-JS continue button is
345	/// the fallback — the whole flow still completes.
346	const WALLET_POLL_SCRIPT: &str = r#"    <script>
347	    (function(){
348	      var el=document.getElementById('wallet-path');
349	      if(!el)return;
350	      var rid=el.getAttribute('data-request-id');
351	      var status=document.getElementById('wallet-status');
352	      var form=document.getElementById('complete-form');
353	      var interval=3000;
354	      function schedule(){setTimeout(poll,interval);}
355	      function poll(){
356	        fetch('/oauth/authorize/status?request_id='+encodeURIComponent(rid),{headers:{'Accept':'application/json'}})
357	          .then(function(r){
358	            if(r.status===429){interval=Math.min(interval+2000,15000);schedule();return null;}
359	            return r.json();
360	          })
361	          .then(function(d){
362	            if(!d)return;
363	            if(d.status==='approved'){status.textContent='Approved — continuing…';form.submit();return;}
364	            if(d.status==='denied'){status.textContent='This request was denied in your wallet.';return;}
365	            if(d.status==='expired'){status.textContent='This request expired. Reload the page to try again.';return;}
366	            if(d.status==='completed'){return;}
367	            schedule();
368	          })
369	          .catch(function(){schedule();});
370	      }
371	      schedule();
372	    })();
373	    </script>
374	"#;
375	
376	// ── Pure helpers ──────────────────────────────────────────────────────────────
377	
378	/// Percent-encode a string for safe inclusion as a URL query parameter value.
379	pub(super) fn encode_param(s: &str) -> String {
380	    let mut out = String::with_capacity(s.len());
381	    for b in s.bytes() {
382	        match b {
383	            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
384	                out.push(b as char)
385	            }
386	            _ => out.push_str(&format!("%{b:02X}")),
387	        }
388	    }
389	    out
390	}
391	
392	/// Render `data` as an inline, self-contained SVG QR code, or `None` if it does not fit in a QR
393	/// (the caller then falls back to the typed code, never breaking the page). Dark modules are drawn
394	/// as one `<path>` on a white ground with a 4-module quiet zone — dark-on-light with a fixed white
395	/// background so it scans regardless of the viewer's page theme. Pure: no I/O, deterministic.
396	fn render_qr_svg(data: &str) -> Option<String> {
397	    // Medium error correction balances density against scan robustness on a phone camera.
398	    let qr = qrcodegen::QrCode::encode_text(data, qrcodegen::QrCodeEcc::Medium).ok()?;
399	    const QUIET: i32 = 4;
400	    let size = qr.size();
401	    let dim = size + 2 * QUIET;
402	
403	    // One path of "M{x} {y}h1v1h-1z" per dark module — compact and crisp at any rendered size.
404	    use std::fmt::Write as _;
405	    let mut modules = String::new();
406	    for y in 0..size {
407	        for x in 0..size {
408	            if qr.get_module(x, y) {
409	                let _ = write!(modules, "M{} {}h1v1h-1z", x + QUIET, y + QUIET);
410	            }
411	        }
412	    }
413	
414	    Some(format!(
415	        "<svg viewBox=\"0 0 {dim} {dim}\" width=\"196\" height=\"196\" role=\"img\" \
416	         aria-label=\"QR code to sign in with the Obsign wallet\" \
417	         xmlns=\"http://www.w3.org/2000/svg\" shape-rendering=\"crispEdges\">\
418	         <rect width=\"{dim}\" height=\"{dim}\" fill=\"#ffffff\"/>\
419	         <path d=\"{modules}\" fill=\"#1b1b1f\"/></svg>"
420	    ))
421	}
