783	            "https://app.example.com/client-metadata.json",
784	            "https://app.example.com/callback",
785	            "challenge",
786	            "S256",
787	            "state",
788	            "atproto",
789	            "code",
790	            "https://pds.example.com",
791	            None,
792	            None,
793	            Some(&wallet),
794	        );
795	        // Scan QR present as a self-contained inline SVG.
796	        assert!(html.contains("<svg"), "the scan QR SVG must render");
797	        assert!(
798	            html.contains("aria-label=\"QR code to sign in with the Obsign wallet\""),
799	            "the QR SVG must carry an accessible label"
800	        );
801	        // Typed code fallback present alongside it.
802	        assert!(
803	            html.contains("4QX9-TX7P"),
804	            "the typed user_code fallback must remain rendered"
805	        );
806	        // Same-device handoff link carries the request_id.
807	        assert!(
808	            html.contains("consent?request_id=poauth_abcDEF123"),
809	            "the handoff link must carry the request_id"
810	        );
811	    }
812	
813	    /// The handoff URI carries the request_id (and origin when present) under the wallet's
814	    /// private-use scheme — the payload the QR encodes and the same-device link targets.
815	    #[test]
816	    fn wallet_handoff_uri_encodes_request_id_and_origin() {
817	        let uri = wallet_handoff_uri("poauth_xyz", Some("https://app.example.com"));
818	        assert!(uri.starts_with("org.obsign.identitywallet:/consent?request_id=poauth_xyz"));
819	        assert!(uri.contains("&origin=https%3A%2F%2Fapp.example.com"));
820	        // Origin is optional — a request created without an Origin/Referer header omits it.
821	        let bare = wallet_handoff_uri("poauth_xyz", None);
822	        assert_eq!(
823	            bare,
824	            "org.obsign.identitywallet:/consent?request_id=poauth_xyz"
825	        );
826	    }
827	
828	    /// The QR renderer produces a self-contained SVG that scans dark-on-white regardless of page
829	    /// theme, and reports `None` only when the data cannot fit in a QR at all.
830	    #[test]
831	    fn render_qr_svg_produces_a_self_contained_svg() {
832	        let svg = render_qr_svg("org.obsign.identitywallet:/consent?request_id=poauth_abc")
833	            .expect("a short payload always fits in a QR");
834	        assert!(svg.starts_with("<svg"));
835	        assert!(svg.contains("viewBox="));
836	        assert!(
837	            svg.contains("fill=\"#ffffff\""),
838	            "white ground for scanning"
839	        );
840	        assert!(svg.contains("<path"), "dark modules drawn as a path");
841	        // No external resource fetches — the SVG must be fully inline (the `xmlns` namespace URI is a
842	        // declaration, not a fetch); nothing loads over the network, matching the auth page rule.
843	        assert!(!svg.contains("href") && !svg.contains("<image") && !svg.contains("src="));
844	    }
845	}
