#[cfg(test)]
mod tests {
    use super::*;
    use axum::response::IntoResponse;

    /// `error_redirect` must emit the RFC 9207 `iss` parameter (the AS metadata advertises
    /// `authorization_response_iss_parameter_supported: true`), alongside the error, its
    /// description, and the round-tripped `state`.
    #[test]
    fn error_redirect_includes_iss_and_error_params() {
        let redirect = error_redirect(
            "https://app.example.com/callback",
            "access_denied",
            "User denied access",
            "teststate",
            "https://pds.example.com",
        );
        let location = redirect
            .into_response()
            .headers()
            .get("location")
            .unwrap()
            .to_str()
            .unwrap()
            .to_string();
        assert!(location.contains("error=access_denied"), "{location}");
        assert!(location.contains("state=teststate"), "{location}");
        assert!(
            location.contains("iss=https%3A%2F%2Fpds.example.com"),
            "error redirect must carry the iss parameter: {location}"
        );
    }

    /// Every `granted_scope` checkbox must be a member of the consent <form> —
    /// controls outside the form element are silently omitted from the POST, which
    /// would strip every non-`atproto` grant the user approved (the consent
    /// reduction filter only grants tokens echoed back in `granted_scope`).
    #[test]
    fn granted_scope_checkboxes_are_inside_the_consent_form() {
        let html = render_consent_page(
            "Test App",
            "https://app.example.com/client-metadata.json",
            "https://app.example.com/callback",
            "challenge",
            "S256",
            "state",
            "atproto transition:generic repo:app.bsky.feed.post",
            "code",
            "https://pds.example.com",
            None,
            None,
            None,
        );

        let form_open = html.find("<form").expect("consent form present");
        let form_close = html.find("</form>").expect("consent form closed");
        let mut checkbox_count = 0;
        for (idx, _) in html.match_indices("name=\"granted_scope\"") {
            checkbox_count += 1;
            assert!(
                idx > form_open && idx < form_close,
                "granted_scope input at byte {idx} is outside the <form> \
                 ({form_open}..{form_close}) and would not be submitted"
            );
        }
        assert!(
            checkbox_count >= 2,
            "expected a checkbox per non-atproto scope token, found {checkbox_count}"
        );
    }

    /// The identifier field must disable iOS auto-capitalization/autocorrect/spellcheck —
    /// handles and DIDs are case-sensitive lowercase strings, and a capitalized first letter
    /// silently breaks sign-in.
    #[test]
    fn identifier_input_disables_autocapitalization() {
        let html = render_consent_page(
            "Test App",
            "https://app.example.com/client-metadata.json",
            "https://app.example.com/callback",
            "challenge",
            "S256",
            "state",
            "atproto",
            "code",
            "https://pds.example.com",
            None,
            None,
            None,
        );

        // Isolate the identifier input so the attribute assertions can't match another element.
        let input = html
            .split("name=\"identifier\"")
            .nth(1)
            .and_then(|rest| rest.split("/>").next())
            .expect("identifier input present");
        assert!(
            input.contains("autocapitalize=\"none\""),
            "identifier input must set autocapitalize=none"
        );
        assert!(
            input.contains("autocorrect=\"off\""),
            "identifier input must set autocorrect=off"
        );
        assert!(
            input.contains("spellcheck=\"false\""),
            "identifier input must set spellcheck=false"
        );
    }

    /// The wallet path renders BOTH the scan QR (an inline SVG) and the typed `user_code` fallback,
    /// so the phone-scan channel and the no-camera / accessibility channel are always present
    /// together — the typed code is never dropped in favor of the QR.
    #[test]
    fn wallet_path_renders_qr_and_the_typed_code_fallback() {
        let wallet = WalletConsentPath {
            user_code: "4QX9-TX7P",
            request_id: "poauth_abcDEF123",
            origin: Some("https://app.example.com"),
        };
        let html = render_consent_page(
            "Test App",
            "https://app.example.com/client-metadata.json",
            "https://app.example.com/callback",
            "challenge",
            "S256",
            "state",
            "atproto",
            "code",
            "https://pds.example.com",
            None,
            None,
            Some(&wallet),
        );
        // Scan QR present as a self-contained inline SVG.
        assert!(html.contains("<svg"), "the scan QR SVG must render");
        assert!(
            html.contains("aria-label=\"QR code to sign in with the Obsign wallet\""),
            "the QR SVG must carry an accessible label"
        );
        // Typed code fallback present alongside it.
        assert!(
            html.contains("4QX9-TX7P"),
            "the typed user_code fallback must remain rendered"
        );
        // Same-device handoff link carries the request_id.
        assert!(
            html.contains("consent?request_id=poauth_abcDEF123"),
            "the handoff link must carry the request_id"
        );
    }

    /// The handoff URI carries the request_id (and origin when present) under the wallet's
    /// private-use scheme — the payload the QR encodes and the same-device link targets.
    #[test]
    fn wallet_handoff_uri_encodes_request_id_and_origin() {
        let uri = wallet_handoff_uri("poauth_xyz", Some("https://app.example.com"));
        assert!(uri.starts_with("org.obsign.identitywallet:/consent?request_id=poauth_xyz"));
        assert!(uri.contains("&origin=https%3A%2F%2Fapp.example.com"));
        // Origin is optional — a request created without an Origin/Referer header omits it.
        let bare = wallet_handoff_uri("poauth_xyz", None);
        assert_eq!(
            bare,
            "org.obsign.identitywallet:/consent?request_id=poauth_xyz"
        );
    }

    /// The QR renderer produces a self-contained SVG that scans dark-on-white regardless of page
    /// theme, and reports `None` only when the data cannot fit in a QR at all.
    #[test]
    fn render_qr_svg_produces_a_self_contained_svg() {
        let svg = render_qr_svg("org.obsign.identitywallet:/consent?request_id=poauth_abc")
            .expect("a short payload always fits in a QR");
        assert!(svg.starts_with("<svg"));
        assert!(svg.contains("viewBox="));
        assert!(
            svg.contains("fill=\"#ffffff\""),
            "white ground for scanning"
        );
        assert!(svg.contains("<path"), "dark modules drawn as a path");
        // No external resource fetches — the SVG must be fully inline (the `xmlns` namespace URI is a
        // declaration, not a fetch); nothing loads over the network, matching the auth page rule.
        assert!(!svg.contains("href") && !svg.contains("<image") && !svg.contains("src="));
    }
